      handleCreateRelationsInRoam: (args: {
        arrow: DiscourseRelationShape;
        targetId: TLShapeId;
      }) => Promise<void>;
    };
    await (util as UtilWithRoamPersistence).handleCreateRelationsInRoam({
      arrow,
      targetId,
    });
  }
};

